begin;
create table if not exists app_private.operator_usage_events (
 sequence bigint generated by default as identity primary key, event_id uuid not null unique, actor_id uuid not null,
 at timestamptz not null default now(), action text not null, section text not null, product text not null default ''
);
create index if not exists operator_usage_events_at on app_private.operator_usage_events(at desc,sequence desc);
create table if not exists app_private.operator_usage_daily (
 day date not null,actor_id uuid not null,action text not null,section text not null,product text not null default '',hits integer not null default 0 check(hits>=0),
 primary key(day,actor_id,action,section,product)
);
alter table app_private.operator_usage_events enable row level security;
alter table app_private.operator_usage_daily enable row level security;
revoke all on app_private.operator_usage_events,app_private.operator_usage_daily from public,anon,authenticated;
grant all on app_private.operator_usage_events,app_private.operator_usage_daily to service_role;
grant usage,select on sequence app_private.operator_usage_events_sequence_seq to service_role;
create or replace function public.lothuus_admin_usage(actor uuid,events jsonb) returns void
language plpgsql security invoker set search_path='' as $$
declare e jsonb; a text; s text; p text; added bigint;
begin
 if jsonb_typeof(events)<>'array' or jsonb_array_length(events) not between 1 and 20 or actor is null then raise exception 'INVALID_USAGE'; end if;
 for e in select value from jsonb_array_elements(events) loop
  a:=e->>'action';s:=e->>'section';p:=coalesce(e->>'product','');
  if a is null or a not in ('nav_overview','nav_items','nav_reservations','nav_customers','nav_emails','nav_settings','nav_hearts','nav_hosting','nav_visitors','nav_updates','product_add','product_open','capacity_plans','usage_view','plans_view','usage_refresh','usage_details','plan_pro','plan_business','billing_month','billing_year','payment_capacity','payment_open','payment_close','payment_order','payment_paid','payment_iban','payment_details','payment_cancel','faq_maintenance','faq_backup','faq_free','faq_availability') or s is null or s not in ('overview','items','reservations','customers','emails','settings','hearts','hosting','visitors','updates') or p not in ('','pro_month','pro_year','premium_month','premium_year','extra50','extra150') then raise exception 'INVALID_USAGE'; end if;
  added:=null;
  insert into app_private.operator_usage_events(event_id,actor_id,action,section,product) values((e->>'id')::uuid,actor,a,s,p) on conflict(event_id) do nothing returning sequence into added;
  if added is not null then
   insert into app_private.operator_usage_daily(day,actor_id,action,section,product,hits) values((now() at time zone 'Europe/Brussels')::date,actor,a,s,p,1)
   on conflict(day,actor_id,action,section,product) do update set hits=operator_usage_daily.hits+1;
  end if;
 end loop;
end; $$;
create or replace function public.lothuus_operator_usage(actor uuid,period_days integer default 30,before_id bigint default null,category_filter text default 'all') returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;first_day date;
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN';end if;
 if period_days not in (7,30,90) or category_filter not in ('all','packages','usage','workspace') then raise exception 'INVALID_OPERATOR_INPUT';end if;
 first_day:=(now() at time zone 'Europe/Brussels')::date-period_days+1;
 with daily as materialized(select * from app_private.operator_usage_daily where day>=first_day),
 recent as(select sequence,sequence::text as id,at,action,section,product from app_private.operator_usage_events where at>=first_day::timestamp at time zone 'Europe/Brussels' and (before_id is null or sequence<before_id) and (category_filter='all' or category_filter='packages' and (action like 'plan_%' or action like 'billing_%' or action like 'payment_%' or action in ('plans_view','capacity_plans')) or category_filter='usage' and (action like 'usage_%' or action='nav_hosting') or category_filter='workspace' and action not like 'plan_%' and action not like 'billing_%' and action not like 'payment_%' and action not like 'usage_%' and action not in ('plans_view','capacity_plans','nav_hosting')) order by sequence desc limit 50)
 select jsonb_build_object(
 'days',period_days,'recordingSince',(select min(at) from app_private.operator_usage_events),
 'lastInteraction',(select max(at) from app_private.operator_usage_events),
 'totals',(select jsonb_build_object('actions',coalesce(sum(hits) filter(where action not in ('usage_view','plans_view')),0),'hostingOpens',coalesce(sum(hits) filter(where action='nav_hosting'),0),'usageViews',coalesce(sum(hits) filter(where action='usage_view'),0),'usageRefreshes',coalesce(sum(hits) filter(where action='usage_refresh'),0),'plansViews',coalesce(sum(hits) filter(where action='plans_view'),0),'planClicks',coalesce(sum(hits) filter(where action in ('plan_pro','plan_business')),0),'paymentOpens',coalesce(sum(hits) filter(where action='payment_open'),0),'orderClicks',coalesce(sum(hits) filter(where action='payment_order'),0),'paymentClaims',coalesce(sum(hits) filter(where action='payment_paid'),0)) from daily),
 'top',coalesce((select jsonb_agg(to_jsonb(t) order by t.hits desc,t.action) from(select action,sum(hits)::integer as hits from daily where action not in ('usage_view','plans_view') group by action order by hits desc,action limit 20)t),'[]'),
 'products',coalesce((select jsonb_agg(to_jsonb(t) order by t.product) from(select product,sum(hits) filter(where action in ('plan_pro','plan_business')) as clicks,sum(hits) filter(where action='payment_open') as opens,sum(hits) filter(where action='payment_order') as orders,sum(hits) filter(where action='payment_paid') as claims from daily where product<>'' group by product)t),'[]'),
 'daily',coalesce((select jsonb_agg(to_jsonb(t) order by day) from(select day,sum(hits) filter(where action not in ('usage_view','plans_view')) as clicks,sum(hits) filter(where action in ('plan_pro','plan_business','plans_view')) as packages,sum(hits) filter(where action in ('usage_view','usage_refresh','usage_details')) as usage from daily group by day)t),'[]'),
 'events',coalesce((select jsonb_agg(to_jsonb(r)-'sequence' order by sequence desc) from recent r),'[]')) into result;
 return result;
end; $$;

-- Granting a package is distinct from claiming a payment; no fictional bank receipt.
create table if not exists app_private.operator_package_grants (
 id uuid primary key,actor_id uuid not null,plan text not null check(plan in ('basis','pro','premium')),starts_at timestamptz not null default now(),ends_at timestamptz,
 reason text not null check(length(trim(reason)) between 3 and 500),created_at timestamptz not null default now()
);
alter table app_private.operator_package_grants enable row level security;
revoke all on app_private.operator_package_grants from public,anon,authenticated;
grant all on app_private.operator_package_grants to service_role;
create or replace function public.lothuus_operator_grant_package(actor uuid,grant_key uuid,target_plan text,until_at timestamptz,expected_updated timestamptz,reason text,provisioned boolean) returns void
language plpgsql security invoker set search_path='' as $$
declare a app_private.hosting_account;previous app_private.operator_package_grants;
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN';end if;
 if target_plan not in ('basis','pro','premium') or length(trim(reason)) not between 3 and 500 or (target_plan<>'basis' and (until_at is null or until_at<=now() or until_at>now()+interval '5 years' or provisioned is not true)) or (target_plan='basis' and until_at is not null) then raise exception 'INVALID_OPERATOR_INPUT';end if;
 select * into a from app_private.hosting_account where id for update;
 if not found then raise exception 'HOSTING_ACCOUNT_UNAVAILABLE';end if;
 select * into previous from app_private.operator_package_grants where id=grant_key;
 if found then
  if previous.actor_id<>actor or previous.plan<>target_plan or previous.ends_at is distinct from until_at or previous.reason<>trim(reason) then raise exception 'OPERATOR_VERSION_CONFLICT';end if;
  return;
 end if;
 if a.updated_at is distinct from expected_updated then raise exception 'OPERATOR_VERSION_CONFLICT';end if;
 insert into app_private.operator_package_grants(id,actor_id,plan,ends_at,reason) values(grant_key,actor,target_plan,until_at,trim(reason));
 update app_private.hosting_account set plan=target_plan,valid_until=until_at,updated_at=now() where id;
 insert into app_private.operator_activity(actor_id,kind,title,details) values(actor,'package_granted',case target_plan when 'basis' then 'Free handmatig ingesteld' when 'pro' then 'Pro handmatig toegekend' else 'Business handmatig toegekend' end,jsonb_build_object('reason',trim(reason),'until',until_at,'beforePlan',a.plan,'beforeValidUntil',a.valid_until,'paymentConfirmed',false));
end; $$;
create or replace function public.lothuus_operator_package_state(actor uuid) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
begin
 if not public.lothuus_operator_enabled(actor) then raise exception 'OPERATOR_FORBIDDEN';end if;
 return jsonb_build_object('account',(select jsonb_build_object('plan',plan,'validUntil',valid_until,'updatedAt',updated_at) from app_private.hosting_account where id),
 'grants',coalesce((select jsonb_agg(to_jsonb(g) order by created_at desc) from(select id,plan,starts_at,ends_at,reason,created_at from app_private.operator_package_grants order by created_at desc limit 30)g),'[]'));
end; $$;
select cron.schedule('lothuus-workspace-usage-retention','53 3 * * *',$$delete from app_private.operator_usage_events where at<now()-interval '90 days';delete from app_private.operator_usage_daily where day<(now() at time zone 'Europe/Brussels')::date-365$$);
create or replace function public.lothuus_backup_state() returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare tables jsonb:='{}';rows jsonb;t text;
begin
 foreach t in array array['store','media','product_numbers','stock_claims','heart_settings','heart_objects','heart_days','analytics_config','analytics_days','hosting_account','hosting_orders','hosting_entitlements','hosting_media_objects','hosting_metrics','hosting_usage_daily','operator_users','operator_settings','operator_activity','operator_notes','operator_versions','operator_jobs','operator_usage_events','operator_usage_daily','operator_package_grants'] loop
 execute format('select coalesce(jsonb_agg(to_jsonb(t)),''[]''::jsonb) from app_private.%I t',t) into rows;tables:=tables||jsonb_build_object(t,rows);
 end loop;
 return jsonb_build_object('schemaVersion',2,'createdAt',now(),'tables',tables);
end; $$;
do $$declare f record;begin
 for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('lothuus_admin_usage','lothuus_operator_usage','lothuus_operator_grant_package','lothuus_operator_package_state') loop
 execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);
 end loop;
end;$$;
commit;
